fn corpus(entries: &[CorpusDelta], case: usize, end: usize, mode: bool, original: u64) -> u64 {
    let key = (case, end, mode);
    if let Ok(i) = entries.binary_search_by_key(&key, |e| e.0) {
        assert_eq!(entries[i].1, original, "shortcut delta predecessor {key:?}");
        entries[i].2
    } else {
        original
    }
}
pub fn root(case: usize, end: usize, mode: bool, original: u64) -> u64 {
    corpus(ROOT, case, end, mode, original)
}
pub fn container(case: usize, end: usize, mode: bool, original: u64) -> u64 {
    corpus(CONTAINER, case, end, mode, original)
}
pub fn source(source: &str, mode: bool, original: u64) -> u64 {
    SOURCES
        .iter()
        .find(|e| e.0 == source && e.1 == mode && e.2 == original)
        .map_or(original, |e| e.3)
}
